  'Media Studio': 'SPECIALIZED_ROOM',
  'Photography Studio': 'SPECIALIZED_ROOM',
  'Film Studio': 'SPECIALIZED_ROOM',
  'Workshop': 'SPECIALIZED_ROOM',
  'Research Room': 'SEMINAR_ROOM',
