  'Innovation Lab': 'SPECIALIZED_ROOM',
  'Robotics Lab': 'SPECIALIZED_ROOM',
  'Electronics Lab': 'SPECIALIZED_ROOM',
  'Demonstration Room': 'SPECIALIZED_ROOM',
